'use strict';
const $=(s,p=document)=>p.querySelector(s);
const $$=(s,p=document)=>[...p.querySelectorAll(s)];
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
const menu=$('.menu-button');
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));menu.setAttribute('aria-label',open?'Open menu':'Close menu');$('#mobile-menu').hidden=open;});
$$('#mobile-menu a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');$('#mobile-menu').hidden=true;}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu?.getAttribute('aria-expanded')==='true'){menu.click();menu.focus();}});
let toastTimer;
function toast(message){const box=$('#toast');if(!box)return;box.textContent=message;box.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.classList.remove('show'),3500);}
async function copy(text,source,status){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);}else{source.focus();source.select();if(!document.execCommand('copy'))throw Error('Copy unavailable');}status.textContent='Copied. Ready to share.';}catch{source.focus();source.select();status.textContent='Select the text and use your device’s Copy option.';}}
const dialog=$('#demo-dialog');
let demoTrigger;
$$('[data-open-demo]').forEach(b=>b.addEventListener('click',()=>{demoTrigger=b;dialog.showModal();}));
$('.dialog-close')?.addEventListener('click',()=>dialog.close());
dialog?.addEventListener('close',()=>demoTrigger?.focus());
dialog?.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
const drafts={clothing:{arrival:'A new season calls for new favourites 👋\n\nOur new collection has arrived! Come explore fresh styles and everyday favourites at our store. We’d love to see you.',festive:'A little festive style, just for you ✨\n\nWe’re welcoming the season with a fresh collection. Drop by and discover something special for your celebrations.',weekend:'Your weekend style starts here 👋\n\nCome explore what’s new in store this weekend. Fresh looks and familiar favourites are waiting for you.'},cafe:{arrival:'Something delicious is on the menu ☕\n\nWe’ve been working on a few new favourites. Stop by, bring your appetite and find your next go-to.',festive:'Good food. Good company. A little celebration ✨\n\nJoin us for our festive menu and make a moment of it. We’d love to welcome you.',weekend:'Your weekend plans just got tastier ☕\n\nExplore our special weekend menu and make time for your favourites. Your table is waiting.'},salon:{arrival:'A fresh hello to a little self-care ✨\n\nDiscover our latest beauty and grooming services. Find a little time for yourself — we’d love to see you.',festive:'A little glow for the celebrations ahead ✨\n\nExplore our seasonal beauty and grooming packages. Get in touch to find a time that works for you.',weekend:'Make a little time for yourself this weekend ✨\n\nExplore our beauty and grooming services and start the week feeling refreshed. Contact us to check availability.'},online:{arrival:'Something new just landed 👋\n\nOur latest collection is here. Explore the new arrivals and discover your next everyday favourite.',festive:'Find a little something for the season ✨\n\nOur festive collection is ready to explore. Discover fresh finds for you and the people you love.',weekend:'A little weekend browsing inspiration 👋\n\nTake a look at what’s new in our collection. Your next favourite might be waiting for you.'}};
$('#demo-form')?.addEventListener('submit',e=>{e.preventDefault();const output=$('#demo-output');$('#demo-draft').value=drafts[$('#demo-business').value][$('#demo-occasion').value]+'\n\nReply STOP to opt out.';output.hidden=false;$('#demo-status').textContent='Sample draft ready. You can edit it below.';$('#demo-draft').focus();output.scrollIntoView({behavior:reducedMotion.matches?'instant':'smooth',block:'nearest'});replayAnimation($('[data-animation="success"]',output));});
$('#copy-draft')?.addEventListener('click',()=>copy($('#demo-draft').value,$('#demo-draft'),$('#demo-status')));
$('#enquiry-form')?.addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));$('#enquiry-text').value=`Hello SaralKaro,\n\nI’m interested in Hello Customer.\n\nName: ${d.name.trim()}\nBusiness: ${d.business.trim()}\nEmail: ${d.email.trim()}\nCity: ${d.city.trim()||'Not specified'}\nCategory: ${d.category}\nEnquiry: ${d.interest}\n\n${d.message.trim()||'Please share the latest launch details and available next steps.'}\n\nThank you.`;const result=$('#enquiry-result');result.hidden=false;replayAnimation($('[data-animation="success"]',result));$('#copy-status').textContent='';result.focus();result.scrollIntoView({behavior:reducedMotion.matches?'instant':'smooth',block:'nearest'});});
$('#copy-enquiry')?.addEventListener('click',()=>copy($('#enquiry-text').value,$('#enquiry-text'),$('#copy-status')));
const caseData=[['FOR CLOTHING STORES','A fresh collection. A familiar hello.','Let the customers who love your style know what’s new.','THE WINTER EDIT','New season.\nNew favourites.','fashion',['Share new collections','Keep your regulars in the loop','Make your next offer feel personal']],['FOR CAFÉS & RESTAURANTS','Give the weekend a little flavour.','Share a special menu with the people who love your place.','THE WEEKEND MENU','Your table\nis waiting.','cafe',['Introduce a seasonal menu','Share weekend specials','Keep regular customers in the loop']],['FOR SALONS','Make their next visit feel special.','Introduce seasonal packages to your regular customers.','A LITTLE SELF CARE','A fresh look.\nA fresh hello.','salon',['Introduce seasonal packages','Share new services','Welcome your regulars back']],['FOR ONLINE SELLERS','New in store. Back in their minds.','Share your latest launch with your opted-in audience.','FRESH FINDS','Meet your next\nfavourite.','online',['Announce a new collection','Share product launches','Stay connected after a purchase']],['FOR HOME & LIVING','A little inspiration for their space.','Bring seasonal collections to the customers who love your store.','ROOM FOR SOMETHING NEW','Fresh finds.\nHappy spaces.','home',['Showcase seasonal collections','Announce new arrivals','Inspire your regular customers']]];
const artShapes={fashion:'<path d="m260 56-48 26 20 42 28-10v112h104V114l28 10 20-42-48-26-25 16h-54l-25-16Z" fill="#e08c57"/><path d="m285 56 4 22 23 22 23-22 4-22M312 100v126M265 153h28v35h-28m66-35h28v35h-28" fill="none" stroke="#a55f3c" stroke-width="3"/><path d="m260 56 25-9 27 17 27-17 25 9-25 30-27-22-27 22-25-30Z" fill="#f3b17c"/>',cafe:'<ellipse cx="326" cy="216" rx="82" ry="14" fill="#693d20" opacity=".15"/><path d="M267 93h112v73c0 61-112 61-112 0V93Z" fill="#f5dfb8"/><ellipse cx="323" cy="93" rx="56" ry="19" fill="#fff0d8"/><ellipse cx="323" cy="94" rx="45" ry="12" fill="#805232"/><path d="M380 105c69-9 46 76-2 66" fill="none" stroke="#f5dfb8" stroke-width="17"/><path d="M307 68c-25-25 17-26 0-52m33 52c-25-25 17-26 0-52" fill="none" stroke="#fff" stroke-width="6" opacity=".7"/>',salon:'<rect x="285" y="30" width="90" height="169" rx="45" fill="#d8c1d8" stroke="#a87ea4" stroke-width="6"/><path d="M330 199v29m-37 0h74" stroke="#a87ea4" stroke-width="6"/><path d="m311 80 41 40m-40 0 40-40" stroke="#fff" stroke-width="4"/><circle cx="308" cy="77" r="9" fill="none" stroke="#fff" stroke-width="4"/><circle cx="308" cy="123" r="9" fill="none" stroke="#fff" stroke-width="4"/>',online:'<path d="M280 95h100l-8 126h-84l-8-126Z" fill="#d8ae83"/><path d="M305 102V78a25 25 0 0 1 50 0v24" fill="none" stroke="#987753" stroke-width="7"/><path d="m317 151 12 12 22-24" stroke="#f8e8d4" stroke-width="7" fill="none"/>',home:'<path d="M278 112h94l-14 113h-66l-14-113Z" fill="#e3aa6b"/><path d="M325 119V62m0 35c-56 0-54-48-54-48s54-3 54 48Zm0-16c48 0 50-48 50-48s-50 0-50 48Z" fill="#748e71"/>'};
function selectCase(index){const [kind,title,desc,kicker,artTitle,art,checks]=caseData[index];$$('[data-case]').forEach((b,i)=>{b.setAttribute('aria-selected',String(i===index));b.tabIndex=i===index?0:-1;});$('#case-panel').setAttribute('aria-labelledby',`case-tab-${index}`);$('#case-kind').textContent=kind;$('#case-title').textContent=title;$('#case-desc').textContent=desc;$('#case-kicker').textContent=kicker;$('#case-art-title').replaceChildren(...artTitle.split('\n').flatMap((line,i)=>i?[document.createElement('br'),document.createTextNode(line)]:[document.createTextNode(line)]));$('#case-artwork').innerHTML=`<svg class="campaign-art ${art}" viewBox="0 0 460 260" aria-hidden="true"><rect width="460" height="260" fill="currentColor" opacity=".12"/><circle cx="366" cy="110" r="120" fill="#fff" opacity=".35"/>${artShapes[art]}</svg>`;$('.case-art').style.background=art==='salon'?'#eee3ee':art==='home'?'#dce6d5':art==='online'?'#e8e2d6':'#eadcc4';$$('.case-copy .check-list li').forEach((li,i)=>{li.lastChild.textContent=' '+checks[i];});}
$$('[data-case]').forEach((b,i,all)=>{b.addEventListener('click',()=>selectCase(i));b.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%all.length;if(e.key==='ArrowLeft')next=(i+all.length-1)%all.length;if(e.key==='Home')next=0;if(e.key==='End')next=all.length-1;if(next!==undefined){e.preventDefault();selectCase(next);all[next].focus();}});});
// The supplied brand files contain static vector shapes with animated layer scale.
// Render those vectors locally and play their original scale keyframes via Web Animations.
const animationCache=new Map();
function shapePath(s){const {v,i,o,c}=s;if(!v?.length)return'';let p=`M${v[0].join(',')}`;for(let n=1;n<v.length;n++){const a=v[n-1],b=v[n];p+=` C${a[0]+o[n-1][0]},${a[1]+o[n-1][1]} ${b[0]+i[n][0]},${b[1]+i[n][1]} ${b.join(',')}`;}if(c){const a=v.at(-1),b=v[0];p+=` C${a[0]+o.at(-1)[0]},${a[1]+o.at(-1)[1]} ${b[0]+i[0][0]},${b[1]+i[0][1]} ${b.join(',')}Z`;}return p;}
function createVectors(items){const ns='http://www.w3.org/2000/svg';const g=document.createElementNS(ns,'g');const fill=items.find(x=>x.ty==='fl');let color='#1f272d';if(fill){color=`rgb(${fill.c.k.slice(0,3).map(n=>Math.round(n*255)).join(',')})`;}for(const item of items){if(item.ty==='sh'){const p=document.createElementNS(ns,'path');p.setAttribute('d',shapePath(item.ks.k));p.setAttribute('fill',color);p.setAttribute('fill-rule',fill?.r===2?'evenodd':'nonzero');g.append(p);}else if(item.ty==='gr')g.append(createVectors(item.it));else if(item.ty==='tr'){const p=item.p?.k||[0,0],a=item.a?.k||[0,0],s=item.s?.k||[100,100];g.setAttribute('transform',`translate(${p[0]} ${p[1]}) rotate(${item.r?.k||0}) scale(${s[0]/100} ${s[1]/100}) translate(${-a[0]} ${-a[1]})`);}}return g;}
async function loadAnimation(el){try{const name=el.dataset.animation;let data=animationCache.get(name);if(!data){data=fetch(`/assets/branding/animations/${name}-animation.json`).then(r=>{if(!r.ok)throw Error('Animation unavailable');return r.json();});animationCache.set(name,data);}data=await data;const ns='http://www.w3.org/2000/svg';const svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox',`0 0 ${data.w} ${data.h}`);svg.setAttribute('aria-hidden','true');for(const layer of data.layers){const root=document.createElementNS(ns,'g');const p=layer.ks.p.k,a=layer.ks.a.k;root.setAttribute('transform',`translate(${p[0]} ${p[1]}) translate(${-a[0]} ${-a[1]})`);const vectors=createVectors(layer.shapes);root.append(vectors);svg.append(root);el._motionTarget=vectors;el._animationData={frames:layer.ks.s.k,duration:(data.op-data.ip)/data.fr*1000,last:data.op-1};}el.replaceChildren(svg);if(el._visible)replayAnimation(el);}catch{/* Preserve the supplied SVG fallback when an animation cannot load. */}}
function replayAnimation(el){
 if(!el?._motionTarget||reducedMotion.matches)return;
 el._running?.cancel();
 const {frames,duration,last}=el._animationData;
 const looping=el.dataset.loop==='true'||['ai-thinking','loading'].includes(el.dataset.animation);
 // Keep the original JSON motion, then give the welcome animation a resting beat.
 const rest=el.dataset.animation==='logo'&&looping?1200:0;
 const total=duration+rest;
 const keys=frames.map(f=>({transform:`scale(${f.s[0]/100},${f.s[1]/100})`,offset:(f.t/last)*(duration/total),easing:'ease-in-out'}));
 if(rest)keys.push({transform:keys.at(-1).transform,offset:1});
 el._running=el._motionTarget.animate(keys,{duration:total,iterations:looping?Infinity:1,fill:'forwards'});
}
const observer=new IntersectionObserver(entries=>entries.forEach(({target,isIntersecting})=>{
 target._visible=isIntersecting;
 if(isIntersecting){
  if(target._animationData){
   if(!target._running||target._running.playState==='finished')replayAnimation(target);
   else target._running.play();
  }else if(!target._loading){target._loading=true;loadAnimation(target);}
 }else target._running?.pause();
}),{threshold:0.12});
$$('[data-animation]').forEach(el=>{
 observer.observe(el);
 el.addEventListener('pointerenter',()=>replayAnimation(el));
});
const onMotionChange=()=>$$('[data-animation]').forEach(el=>{
 if(reducedMotion.matches)el._running?.cancel();
 else if(el._visible)replayAnimation(el);
});
reducedMotion.addEventListener('change',onMotionChange);
